-- PDF-verified initial catalogue. No original grades or custom calculator is overwritten.
begin;
create table if not exists public.study_scheme_templates (
  key text primary key, course_codes jsonb not null, course_titles jsonb not null,
  definition jsonb not null check(public.study_definition_valid(definition)),
  document jsonb not null, created_at timestamptz not null default now()
);
alter table public.study_scheme_templates enable row level security;
alter table public.study_scheme_templates force row level security;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='study_scheme_templates' and policyname='study_templates_read') then
  create policy study_templates_read on public.study_scheme_templates for select to authenticated using(true);
end if; end $$;
revoke all on public.study_scheme_templates from anon,authenticated;
grant select on public.study_scheme_templates to authenticated;
grant all on public.study_scheme_templates to service_role;
