-- Course aliases are imported data, compared exactly, never inferred from similar LMS names.
do $$ declare item record; doc_id uuid; begin
  for item in select c.id course_id,c.user_id,c.metadata,t.* from public.study_courses c join public.study_scheme_templates t
    on exists(select 1 from jsonb_array_elements_text(t.course_codes) a where lower(btrim(a))=lower(btrim(c.code)))
      or exists(select 1 from jsonb_array_elements_text(t.course_titles) a where lower(btrim(a))=lower(btrim(c.title)))
    where c.status='active'
  loop
    select id into doc_id from public.syllabus_documents where user_id=item.user_id and study_course_id=item.course_id and sha256=item.document->>'sha256';
    if doc_id is null then
      insert into public.syllabus_documents(user_id,study_course_id,version,file_name,sha256,extraction_status,source_pages,notes)
        select item.user_id,item.course_id,coalesce(max(version),0)+1,item.document->>'fileName',item.document->>'sha256',item.document->>'extractionStatus',item.document->'sourcePages',coalesce(item.document->'notes','[]'::jsonb)
        from public.syllabus_documents where user_id=item.user_id and study_course_id=item.course_id returning id into doc_id;
    end if;
    if not exists(select 1 from public.grading_schemes where user_id=item.user_id and study_course_id=item.course_id and document_id=doc_id and definition=item.definition) then
      insert into public.grading_schemes(user_id,study_course_id,document_id,version,definition,verification,is_active)
        select item.user_id,item.course_id,doc_id,coalesce(max(version),0)+1,item.definition,'verified',
          not (coalesce(item.metadata,'{}'::jsonb) ? 'study_calculator_v1')
          and not exists(select 1 from public.grading_schemes where user_id=item.user_id and study_course_id=item.course_id and is_active)
        from public.grading_schemes where user_id=item.user_id and study_course_id=item.course_id;
    end if;
  end loop;
end $$;
commit;
